css:
/* 液态玻璃 · 版面重排（自定义主题版：只靠 CSS，不依赖插件）
   目标不是换色，而是换结构：侧栏变浮岛、顶栏变药丸、首页变玻璃便当、
   播放条变悬浮舱。所有规则都挂 html[data-theme] 下，刷新即恢复原版面。 */

/* ---------- 1. 令牌 ---------- */
html[data-theme] {
  color-scheme: dark;
  --bg: #060a13;
  --ink: #eef4ff; --muted: #a7b7d4; --dim: #7788a8;
  --soft: #c9d8ef; --meta: #9fafca; --bright: #ffffff;
  --line: rgba(255, 255, 255, 0.13); --line2: rgba(255, 255, 255, 0.07);
  --accent: #8fe3ff; --accent2: #c9b4ff; --accentText: #04121a;
  --good: #9ff0d0; --warn: #ffd7a1;
  --glow1: rgba(60, 120, 255, 0.22); --glow2: rgba(150, 90, 255, 0.18);
  --panel: rgba(255, 255, 255, 0.055); --panel2: rgba(255, 255, 255, 0.085);
  --dock1: rgba(22, 30, 48, 0.58); --dock2: rgba(9, 14, 26, 0.72);
  --glass: rgba(14, 22, 38, 0.55);
  --track: rgba(255, 255, 255, 0.12); --scroll: rgba(255, 255, 255, 0.18);
  --coverbg: #0d1424;
  --menu: rgba(13, 20, 33, 0.94); --menu1: rgba(24, 34, 52, 0.92); --menu2: rgba(9, 14, 24, 0.96);
  --chev: #8fa4c4;
  --edge: rgba(143, 227, 255, 0.28); --edge2: rgba(201, 180, 255, 0.22);
  --hover: rgba(143, 227, 255, 0.09); --tick: rgba(255, 255, 255, 0.16);
  --inset: rgba(255, 255, 255, 0.4); --wordactive: #ffffff;
  --swborder: rgba(255, 255, 255, 0.26);
  --shadow-dock: 0 30px 80px -22px rgba(0, 5, 16, 0.85), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  --serif: "SF Pro Display", "Segoe UI Variable Display", system-ui, -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
  --bottom: 148px;
  /* 侧栏原来是实色导航，这里改成透明玻璃，文字色一并提亮 */
  --shell-nav: transparent; --shell-nav2: transparent;
  --shell-navin: #eaf4ff; --shell-navmuted: #a9bdd9; --shell-navline: rgba(255, 255, 255, 0.12);
}

/* ---------- 2. 背景：深空 + 漂移光斑 ---------- */
html[data-theme] body {
  background:
    radial-gradient(1200px 620px at 18% -8%, rgba(56, 132, 255, 0.32), transparent 68%),
    radial-gradient(1000px 560px at 88% 4%, rgba(168, 96, 255, 0.26), transparent 70%),
    radial-gradient(900px 520px at 60% 110%, rgba(24, 214, 196, 0.16), transparent 70%),
    linear-gradient(170deg, #070d1a 0%, #05080f 45%, #04060d 100%);
  background-attachment: fixed;
}
/* 光斑用 body 的两个伪元素铺满全屏：自定义主题不能插 JS，所以不依赖 DOM 层。 */
html[data-theme] body::before {
  content: ""; position: fixed; inset: -25vw; z-index: 0; pointer-events: none;
  background:
    radial-gradient(38vw 38vw at 12vw 10vh, rgba(47, 123, 255, 0.42), transparent 62%),
    radial-gradient(34vw 34vw at 88vw 6vh, rgba(163, 92, 255, 0.36), transparent 64%),
    radial-gradient(30vw 30vw at 62vw 100vh, rgba(23, 214, 196, 0.22), transparent 66%);
  filter: blur(64px); animation: lg-breathe 26s ease-in-out infinite alternate;
}
html[data-theme] body::after {
  content: ""; position: fixed; inset: 0; z-index: 0; pointer-events: none; opacity: 0.14; mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='120' height='120' filter='url(%23n)' opacity='0.5'/></svg>");
}
@keyframes lg-breathe {
  from { transform: translate3d(0, 0, 0) scale(1); }
  to { transform: translate3d(3vw, 2vh, 0) scale(1.08); }
}
/* ---------- 3. 外壳：浮岛侧栏 + 药丸顶栏 ---------- */
html[data-theme] .app { background: transparent; grid-template-columns: 276px minmax(0, 1fr); color: var(--ink); }

html[data-theme] .sidebar {
  margin: 14px 0 14px 14px; height: calc(100vh - 28px);
  padding: 20px 12px 92px; border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 30px;
  background:
    linear-gradient(152deg, rgba(255, 255, 255, 0.17) 0%, rgba(255, 255, 255, 0.05) 40%, rgba(8, 14, 26, 0.42) 100%),
    radial-gradient(120% 55% at 0% 0%, rgba(143, 227, 255, 0.16), transparent 62%);
  backdrop-filter: blur(36px) saturate(185%); -webkit-backdrop-filter: blur(36px) saturate(185%);
  box-shadow: 0 34px 80px -34px rgba(0, 0, 0, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.5), inset 0 -1px 0 rgba(255, 255, 255, 0.08);
}

html[data-theme] .brand { padding: 4px 6px 10px; margin-bottom: 6px; border: 0; }
html[data-theme] .brand-mark {
  width: 40px; height: 40px; border-radius: 14px; font-size: 17px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.9), rgba(143, 227, 255, 0.55) 45%, rgba(201, 180, 255, 0.5));
  color: #06101c; border: 0;
  box-shadow: 0 12px 26px -10px rgba(120, 210, 255, 0.8), inset 0 1px 0 rgba(255, 255, 255, 0.9);
}
html[data-theme] .brand-name { letter-spacing: -0.02em; }
html[data-theme] .brand-sub { color: #8fa8c8; letter-spacing: 0.22em; }

html[data-theme] .nav-label { margin: 16px 8px 8px; color: #8ba2c2; letter-spacing: 0.2em; }
html[data-theme] .nav button {
  border-radius: 14px; padding: 9px 11px; margin-bottom: 3px;
  border: 1px solid transparent; transition: background 0.16s, border-color 0.16s, color 0.16s, transform 0.16s;
}
html[data-theme] .nav button:hover { background: rgba(255, 255, 255, 0.08); border-color: rgba(255, 255, 255, 0.1); transform: translateX(2px); }
html[data-theme] .nav button.active,
html[data-theme] .nav button.on {
  color: #ffffff; border-color: rgba(143, 227, 255, 0.42);
  background: linear-gradient(120deg, rgba(143, 227, 255, 0.26), rgba(201, 180, 255, 0.16));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.4), 0 10px 24px -14px rgba(143, 227, 255, 0.9);
}
html[data-theme] .nav-ico { opacity: 0.8; }
html[data-theme] .sidebar-bottom { padding: 14px 4px 0; }
html[data-theme] .sidebar-add {
  border-radius: 14px; background: linear-gradient(120deg, #9fe8ff, #c9b4ff); color: #06101c;
  box-shadow: 0 14px 28px -14px rgba(160, 220, 255, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

html[data-theme] .main { padding: 0 26px 160px; scroll-padding-top: 96px; }

html[data-theme] .topbar {
  top: 14px; height: 64px; margin: 14px 0 0; padding: 0 12px 0 16px;
  border: 1px solid rgba(255, 255, 255, 0.18); border-radius: 22px;
  background: linear-gradient(150deg, rgba(255, 255, 255, 0.15), rgba(255, 255, 255, 0.04) 55%, rgba(10, 16, 30, 0.22));
  backdrop-filter: blur(30px) saturate(180%); -webkit-backdrop-filter: blur(30px) saturate(180%);
  box-shadow: 0 20px 50px -28px rgba(0, 0, 0, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.45);
}
html[data-theme] .crumb b { letter-spacing: -0.01em; }
html[data-theme] .search-global {
  border-radius: 999px; border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(6, 10, 20, 0.4); padding: 0 12px;
}
html[data-theme] .search-global input { background: transparent; }
html[data-theme] .icon-btn, html[data-theme] .rail-toggle {
  border-radius: 12px; border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.06); color: var(--soft);
}
html[data-theme] .icon-btn:hover, html[data-theme] .rail-toggle:hover { background: rgba(255, 255, 255, 0.14); color: #fff; border-color: rgba(143, 227, 255, 0.45); }

html[data-theme] .theme-pop {
  border-radius: 20px; border: 1px solid rgba(255, 255, 255, 0.2);
  background: linear-gradient(160deg, rgba(30, 40, 62, 0.85), rgba(10, 16, 28, 0.92));
  backdrop-filter: blur(26px) saturate(160%);
  box-shadow: 0 26px 60px -30px rgba(0, 0, 0, 0.95), inset 0 1px 0 rgba(255, 255, 255, 0.4);
}
html[data-theme] .swatch { border-radius: 12px; }

/* ---------- 4. 首页：玻璃便当 ---------- */
html[data-theme] .ledger-home { max-width: 1240px; padding: 30px 0 140px; }

html[data-theme] .ledger-mast {
  display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(250px, 0.75fr);
  gap: 26px; align-items: stretch; position: relative; overflow: hidden;
  padding: 34px 34px 32px; border-bottom: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 34px;
  background:
    linear-gradient(150deg, rgba(255, 255, 255, 0.17) 0%, rgba(255, 255, 255, 0.05) 42%, rgba(9, 16, 30, 0.34) 100%),
    radial-gradient(90% 80% at 8% 0%, rgba(143, 227, 255, 0.16), transparent 60%);
  box-shadow: 0 46px 100px -46px rgba(0, 0, 0, 0.95), 0 0 0 1px rgba(255, 255, 255, 0.05), inset 0 1px 0 rgba(255, 255, 255, 0.55), inset 0 -1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(30px) saturate(170%); -webkit-backdrop-filter: blur(30px) saturate(170%);
}
html[data-theme] .ledger-mast::before {
  content: ""; position: absolute; left: -30%; top: -70%; width: 70%; height: 150%;
  background: linear-gradient(115deg, rgba(255, 255, 255, 0.22), transparent 55%);
  transform: rotate(8deg); pointer-events: none;
}
html[data-theme] .ledger-mast::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none;
  background: radial-gradient(120% 60% at 110% 120%, rgba(201, 180, 255, 0.18), transparent 60%);
}
html[data-theme] .ledger-mast > * { position: relative; z-index: 1; }
html[data-theme] .ledger-mast h1 {
  font: 600 clamp(46px, 5.6vw, 78px)/0.95 var(--sans);
  letter-spacing: -0.05em; margin: 10px 0 20px;
  background: linear-gradient(180deg, #ffffff 0%, #d7e7ff 55%, #8fe3ff 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  -webkit-text-fill-color: transparent;
}
html[data-theme] .ledger-mast h1 em {
  font-style: normal;
  background: linear-gradient(120deg, #9fe8ff, #c9b4ff);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
}
html[data-theme] .ledger-mast p { color: #b7c8e2; font: 400 15px/1.75 var(--sans); max-width: 520px; }
html[data-theme] .ledger-mast .eyebrow { color: #9adfff; letter-spacing: 0.22em; }

html[data-theme] .ledger-search {
  max-width: none; margin-top: 6px; padding: 6px 8px 6px 16px;
  border: 1px solid rgba(255, 255, 255, 0.16); border-radius: 999px;
  background: rgba(5, 10, 20, 0.42);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12), 0 12px 30px -22px rgba(0, 0, 0, 0.9);
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
}
html[data-theme] .ledger-search button {
  width: 38px; height: 38px; border: 0; border-radius: 50%; color: #06101c;
  background: linear-gradient(130deg, #9fe8ff, #c9b4ff);
  box-shadow: 0 10px 24px -12px rgba(160, 220, 255, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.85);
}
html[data-theme] .ledger-search button:hover { filter: brightness(1.08); color: #06101c; }

html[data-theme] .ledger-editor {
  border: 1px solid rgba(255, 255, 255, 0.14); border-left: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 24px; padding: 22px 22px 20px;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.03));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35), 0 20px 45px -30px rgba(0, 0, 0, 0.9);
  display: flex; flex-direction: column; justify-content: center;
}
html[data-theme] .ledger-editor p { color: #b7c8e2; }
html[data-theme] .ledger-sub { color: #9fb2cf; }
html[data-theme] .ledger-sub b { color: #9fe8ff; font-weight: 600; }

html[data-theme] .ledger-rule { display: none; }
html[data-theme] .ledger-section { margin: 38px 0 14px; padding: 0 4px; border: 0; }
html[data-theme] .ledger-section h3 { font: 600 20px/1.2 var(--sans); letter-spacing: -0.02em; }
html[data-theme] .ledger-section small { color: #8ea4c4; letter-spacing: 0.1em; }

html[data-theme] .ledger-home .continue {
  grid-template-columns: 150px minmax(0, 1fr) 58px; gap: 24px; align-items: center;
  margin: 0 0 14px; padding: 16px 22px 16px 16px; border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 28px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0.03) 60%, rgba(10, 18, 32, 0.3));
  box-shadow: 0 26px 60px -42px rgba(0, 0, 0, 0.95), inset 0 1px 0 rgba(255, 255, 255, 0.4);
  backdrop-filter: blur(22px) saturate(160%); -webkit-backdrop-filter: blur(22px) saturate(160%);
  transition: transform 0.2s var(--ease), border-color 0.2s, box-shadow 0.2s;
}
html[data-theme] .ledger-home .continue:hover {
  transform: translateY(-2px); border-color: rgba(143, 227, 255, 0.42);
  box-shadow: 0 34px 70px -40px rgba(0, 0, 0, 0.98), 0 0 0 1px rgba(143, 227, 255, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.5);
}
html[data-theme] .ledger-home .continue .pod-art { width: 150px; height: 150px; border-radius: 20px; box-shadow: 0 16px 34px -20px rgba(0, 0, 0, 0.9); }
html[data-theme] .ledger-home .continue-main strong { font: 600 26px/1.25 var(--sans); letter-spacing: -0.02em; }
html[data-theme] .ledger-home .continue-main span { color: #9fb2cf; }
html[data-theme] .ledger-home .progress { height: 4px; border-radius: 99px; background: rgba(255, 255, 255, 0.1); }
html[data-theme] .ledger-home .round-play {
  width: 50px; height: 50px; border: 0; border-radius: 50%; color: #05101b;
  background: linear-gradient(140deg, #9fe8ff, #c9b4ff);
  box-shadow: 0 16px 34px -14px rgba(160, 220, 255, 0.85), inset 0 1px 0 rgba(255, 255, 255, 0.85);
}
html[data-theme] .ledger-home .round-play:hover { color: #05101b; filter: brightness(1.1); }

html[data-theme] .ledger-rows { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 26px; padding: 6px 4px 0; }
html[data-theme] .ledger-rows .ep-row {
  padding: 12px 10px; border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px; transition: background 0.16s;
}
html[data-theme] .ledger-rows .ep-row:hover { background: rgba(255, 255, 255, 0.06); }
html[data-theme] .ledger-rows .ep-art { width: 42px; height: 42px; flex-basis: 42px; border-radius: 12px; }
html[data-theme] .ledger-rows .ep-title { font: 500 15px/1.45 var(--sans); color: #e8f1ff; }
html[data-theme] .ep-row .ep-title { color: #e8f1ff; }
html[data-theme] .ep-row .ep-sub { color: #9db0cd; }

html[data-theme] .ledger-home .pod-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; margin-top: 10px; }
html[data-theme] .ledger-home .pod-card {
  border: 1px solid rgba(255, 255, 255, 0.14); border-radius: 24px; padding: 12px;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.025) 65%, rgba(10, 18, 32, 0.24));
  box-shadow: 0 22px 50px -40px rgba(0, 0, 0, 0.95), inset 0 1px 0 rgba(255, 255, 255, 0.28);
  backdrop-filter: blur(16px) saturate(150%); -webkit-backdrop-filter: blur(16px) saturate(150%);
  transition: transform 0.18s var(--ease), border-color 0.18s, box-shadow 0.18s;
}
html[data-theme] .ledger-home .pod-card:hover {
  transform: translateY(-4px); border-color: rgba(143, 227, 255, 0.4);
  box-shadow: 0 34px 64px -38px rgba(0, 0, 0, 0.98), 0 0 0 1px rgba(143, 227, 255, 0.2);
}
html[data-theme] .ledger-home .pod-card .pod-art { aspect-ratio: 1 / 1; border-radius: 18px; }
html[data-theme] .ledger-home .pod-card strong { font: 600 16px/1.35 var(--sans); }

html[data-theme] .ledger-home #homeStats { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; border: 0; margin-top: 28px; }
html[data-theme] .ledger-home #homeStats .stat {
  border: 1px solid rgba(255, 255, 255, 0.13); border-radius: 22px; padding: 18px 18px 16px;
  background: linear-gradient(150deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.03));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.3);
}
html[data-theme] .ledger-home #homeStats .stat strong { font: 600 26px/1.1 var(--sans); color: #fff; }

/* ---------- 5. 通用卡片与控件 ---------- */
html[data-theme] .page-head h1 { font: 600 clamp(26px, 2.6vw, 34px)/1.15 var(--sans); letter-spacing: -0.03em; }
html[data-theme] .eyebrow { color: #9adfff; }
html[data-theme] .subtitle { color: #a9bad6; }

html[data-theme] .card {
  border: 1px solid rgba(255, 255, 255, 0.14); border-radius: 26px;
  background: linear-gradient(155deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.03) 60%, rgba(10, 18, 32, 0.22));
  box-shadow: 0 30px 70px -50px rgba(0, 0, 0, 0.95), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  backdrop-filter: blur(18px) saturate(150%); -webkit-backdrop-filter: blur(18px) saturate(150%);
}
html[data-theme] .pod-card {
  border: 1px solid rgba(255, 255, 255, 0.13); border-radius: 20px;
  background: rgba(255, 255, 255, 0.05);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.22);
}
html[data-theme] .pod-card:hover { transform: translateY(-3px); border-color: rgba(143, 227, 255, 0.4); }
html[data-theme] .stat { border-radius: 20px; background: rgba(255, 255, 255, 0.05); border-color: rgba(255, 255, 255, 0.12); }

html[data-theme] .btn { border-radius: 999px; border-color: rgba(255, 255, 255, 0.16); background: rgba(255, 255, 255, 0.07); }
html[data-theme] .btn:hover { background: rgba(255, 255, 255, 0.14); border-color: rgba(143, 227, 255, 0.4); }
html[data-theme] .btn.primary {
  border: 0; color: #05101b;
  background: linear-gradient(130deg, #9fe8ff, #c9b4ff);
  box-shadow: 0 16px 34px -16px rgba(160, 220, 255, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.85);
}
html[data-theme] .btn.primary:hover { filter: brightness(1.08); color: #05101b; }

html[data-theme] input, html[data-theme] select, html[data-theme] textarea {
  border-radius: 12px;
}
html[data-theme] .search-box {
  border: 1px solid rgba(255, 255, 255, 0.12); border-radius: 999px;
  background: rgba(6, 11, 21, 0.4); padding: 4px 14px;
}
html[data-theme] .search-box input { background: transparent; }

/* ---------- 6. 播放条：悬浮舱 ---------- */
/* 首页/设置这条是 .mini-player（.dock 在非 player-open 时是 display:none）。
   它原生是 left:258px + right:20px，也就是“从侧栏右边一直拉到右留白 20”，
   主题这里显式写住同一套几何，别再用 left:auto —— 那会把整条缩成内容宽度。 */
html[data-theme] .mini-player {
  left: 258px; right: 20px; bottom: 14px; border-radius: 26px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: linear-gradient(160deg, rgba(40, 52, 76, 0.52), rgba(9, 14, 26, 0.74));
  backdrop-filter: blur(30px) saturate(180%); -webkit-backdrop-filter: blur(30px) saturate(180%);
  box-shadow: 0 30px 74px -30px rgba(0, 4, 14, 0.95), inset 0 1px 0 rgba(255, 255, 255, 0.4);
}
@media (max-width: 1180px) {
  html[data-theme] .mini-player { left: 220px; }
}
@media (max-width: 900px) {
  html[data-theme] .mini-player { left: 10px; right: 10px; bottom: 64px; border-radius: 20px; }
}
html[data-theme] .mini-player::before {
  content: ""; position: absolute; left: 16px; right: 16px; top: 0; height: 1px; pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.6), transparent);
}
html[data-theme] .mini-cover { border-radius: 16px; }
html[data-theme] .mini-play {
  border-radius: 50%; color: #05101b;
  background: linear-gradient(140deg, #9fe8ff, #c9b4ff);
  box-shadow: 0 14px 30px -12px rgba(160, 220, 255, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.85);
}
html[data-theme] .mini-info strong { font-weight: 600; letter-spacing: -0.01em; }
html[data-theme] .mini-controls .dockicon { border-radius: 50%; }

/* 播放页底栏（.dock）：几何由主题自己写住，不再依赖内置的那套
   ——首页/设置态 .dock 是 display:none，真正在显示的是下面的 .mini-player。 */
html[data-theme] body .dock {
  left: 50% !important; right: auto !important; translate: -50% 0 !important; bottom: 16px !important;
  width: min(1040px, calc(100% - 40px)) !important; max-width: none !important; margin: 0 !important;
  padding: 15px 26px 17px;
  border: 1px solid rgba(255, 255, 255, 0.2); border-radius: 30px;
  background: linear-gradient(160deg, rgba(40, 52, 76, 0.58), rgba(10, 16, 28, 0.76));
  backdrop-filter: blur(34px) saturate(190%); -webkit-backdrop-filter: blur(34px) saturate(190%);
  box-shadow: 0 40px 90px -30px rgba(0, 4, 14, 0.95), inset 0 1px 0 rgba(255, 255, 255, 0.42), inset 0 -1px 0 rgba(255, 255, 255, 0.06);
}
/* 字幕页/播放页（停靠态）：内置样式会把整条摊成 left:0/width:100% 贴底满宽，
   这里改成 880 窄舱 + 左右 0/margin auto 居中，别靠 left:50% 猜状态。 */
html[data-theme] body.player-open .dock {
  left: 0 !important; right: 0 !important; translate: none !important; bottom: 16px !important;
  width: auto !important; max-width: min(880px, calc(100vw - 40px)) !important; margin: 0 auto !important;
}
/* 防御：容器一旦带了 transform/filter/contain，position:fixed 就会被它困住，
   left:50% 也会按容器算而不是按窗口算。这些容器本来就不该有这些属性。 */
html[data-theme] .app, html[data-theme] .main, html[data-theme] .reader, html[data-theme] .stage {
  transform: none !important; filter: none !important; perspective: none !important;
  contain: none !important; will-change: auto !important;
}
html[data-theme] .dock::before {
  content: ""; position: absolute; left: 18px; right: 18px; top: 0; height: 1px; pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.55), transparent);
}
html[data-theme] .track::before { height: 5px; border-radius: 99px; background: rgba(255, 255, 255, 0.1); }
html[data-theme] .pfill { height: 5px; border-radius: 99px; background: linear-gradient(90deg, #9fe8ff, #c9b4ff); box-shadow: 0 0 14px rgba(143, 227, 255, 0.5); }
html[data-theme] .playbtn {
  border: 0; border-radius: 50%; color: #05101b;
  background: linear-gradient(140deg, #9fe8ff, #c9b4ff);
  box-shadow: 0 18px 38px -14px rgba(160, 220, 255, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.85);
}
html[data-theme] .dockicon, html[data-theme] .dockquickbtn { border-radius: 999px; border-color: rgba(255, 255, 255, 0.12); }
html[data-theme] .docksheet {
  border-radius: 24px; border: 1px solid rgba(255, 255, 255, 0.18);
  background: linear-gradient(165deg, rgba(32, 44, 66, 0.82), rgba(10, 16, 28, 0.9));
  backdrop-filter: blur(30px) saturate(170%);
}

